from pathlib import Path
import json,hashlib,re
root=Path('physics');base=Path(__file__).parent
before=json.loads((base/'before-index.json').read_text())
changes={}
def alter(id,old,new):
 p='items/'+id+'.md'
 if p not in changes:
  raw=(root/p).read_bytes(); assert hashlib.sha256(raw).hexdigest()==before[p]['raw_sha256'],p
  changes[p]=raw.decode()
 assert changes[p].count(old)==1,(id,old[:100])
 changes[p]=changes[p].replace(old,new)
alter('thm-qsmx-ising-bulk-symbol-gap',r'$\min_k\epsilon(k)^2=h^2+J^2-2|hJ|=(|h|-|J|)^2$',r'$\min_k\epsilon(k)^2=4(h^2+J^2-2|hJ|)=4(|h|-|J|)^2$')
alter('lem-qsmx-modular-strip-analyticity','The estimate and closed-strip continuity were proved in steps 1.1–1.2.','The estimate and closed-strip continuity were proved in steps 1.1 and 2.1.')
alter('lem-qsmx-trace-class-duality','Steps 1.1–5.1 prove finite-rank','Steps 1.1–4.1 prove finite-rank')
alter('lem-qsmx-modular-resolvent-core',r'''5.1 The space $\Delta^{-1/2}M'\Omega$ is dense: $F(y'\Omega)=y'^*\Omega$ and $F=J\Delta^{-1/2}$ give $\Delta^{-1/2}M'\Omega=JM'\Omega$, which is dense by cyclicity of $\Omega$ for $M'$. For $\xi\in D(\Delta^{1/2})\cap D(\Delta^{-1/2})$, choose $y_n'\in M'$ with $\Delta^{-1/2}y_n'\Omega\to(\Delta^{1/2}+\Delta^{-1/2})\xi$. By step 3.1 at $\lambda=1$, choose $y_n\in M$ with $y_n\Omega=(\Delta+1)^{-1}y_n'\Omega$. The spectral multipliers $(\Delta^{1/2}+\Delta^{-1/2})^{-1}$, $\Delta^{1/2}(\Delta+1)^{-1}$, and $\Delta^{-1/2}(\Delta+1)^{-1}$ are bounded, so $y_n\Omega\to\xi$ and $\Delta^{\pm1/2}y_n\Omega\to\Delta^{\pm1/2}\xi$. Thus the core in step 4.1 is dense in the joint graph norms. [F1, F2, F7, step 3.1, step 4.1]''',r'''5.1 The space $\Delta^{-1/2}M'\Omega$ is dense: $F(y'\Omega)=y'^*\Omega$ and $F=J\Delta^{-1/2}$ give $\Delta^{-1/2}M'\Omega=JM'\Omega$, which is dense by cyclicity of $\Omega$ for $M'$. In particular each $y'\Omega$ belongs to $D(\Delta^{-1/2})$. Fix $\xi\in D(\Delta^{1/2})\cap D(\Delta^{-1/2})$ and put $\eta=(\Delta^{1/2}+\Delta^{-1/2})\xi\in H$. Choose $y_n'\in M'$ so that $\eta_n:=\Delta^{-1/2}y_n'\Omega\to\eta$ in $H$. Step 3.1 at $\lambda=1$ supplies $y_n\in M$ with $y_n\Omega=(\Delta+1)^{-1}y_n'\Omega$. The spectral calculus gives $$y_n\Omega=q(\Delta)\eta_n,\qquad \Delta^{1/2}y_n\Omega=a(\Delta)\eta_n,\qquad \Delta^{-1/2}y_n\Omega=b(\Delta)\eta_n,$$ where $q(\lambda)=\sqrt\lambda/(1+\lambda)$, $a(\lambda)=\lambda/(1+\lambda)$ and $b(\lambda)=1/(1+\lambda)$ for $\lambda>0$. These three multipliers are bounded. The identities follow by multiplying their scalar functions on the domain of $\Delta^{-1/2}$; moreover $\lambda^{1/2}q(\lambda)=a(\lambda)$ and $\lambda^{-1/2}q(\lambda)=b(\lambda)$ are bounded, so $q(\Delta)\eta_n$ belongs to both required domains. Applied to $\eta$, the same identities give $q(\Delta)\eta=\xi$, $a(\Delta)\eta=\Delta^{1/2}\xi$ and $b(\Delta)\eta=\Delta^{-1/2}\xi$. Thus convergence of $\eta_n$ in $H$ implies $y_n\Omega\to\xi$ and $\Delta^{\pm1/2}y_n\Omega\to\Delta^{\pm1/2}\xi$. This proves density of the core from step 4.1 in the joint graph norm, without treating $\Delta^{-1/2}$ as a bounded operator. [A1, F1, F2, F7, step 3.1, step 4.1, construct, algebra]''')
alter('def-qsmx-mps-and-transfer','Each local term is positive semidefinite with kernel $\\operatorname{im}\\Gamma_L$, and every finite open MPS formed from the same translation invariant tensor is a zero-energy ground state of $H_{N,L}$.','Each local term is positive semidefinite with kernel $\\operatorname{im}\\Gamma_L$, and $H_{N,L}$ annihilates every finite open MPS formed from the same translation invariant tensor. Every nonzero such vector is a zero-energy ground state of $H_{N,L}$.')
alter('def-qsmx-mps-and-transfer','Each term in $H_{N,L}$ is positive semidefinite by step 1.3, while their sum annihilates the MPS; its energy is therefore zero and is the minimum possible energy. No uniqueness or positive-gap conclusion follows from this argument.','Each term in $H_{N,L}$ is positive semidefinite by step 1.3, and their sum annihilates the MPS. If that vector is nonzero, zero is an eigenvalue and the minimum possible energy, so the vector is a zero-energy ground state. The zero vector is annihilated but supplies no eigenstate: for example, if all tensor matrices vanish, then $\\Gamma_L=0$, $h_L=I$ and $H_{N,L}=(N-L+1)I$, whose ground energy is positive. No uniqueness or positive-gap conclusion for a nonzero MPS follows from this argument.')
alter('def-qsmx-lattice-current-and-limits','Let $\\mathcal H_L$ be a finite-dimensional complex Hilbert space.','Let $\\mathcal H_L$ be a nonzero finite-dimensional complex Hilbert space.')
alter('thm-qsmx-weighted-lieb-robinson',r'''C_B^\Lambda(S,u)\le C_B^\Lambda(S,0)+\frac{2}{\hbar}\sum_{\substack{Z\subseteq\Lambda\\Z\cap S\ne\varnothing}}\sup_{r\in[0,T]}\|\Phi_r(Z)\|\int_0^u C_B^\Lambda(Z,v)\,dv.''',r'''C_B^\Lambda(S,u)\le C_B^\Lambda(S,0)+\frac{2}{\hbar}\sum_{\substack{Z\subseteq\Lambda\\Z\cap S\ne\varnothing}}\int_0^u\|\Phi_v(Z)\|C_B^\Lambda(Z,v)\,dv.''')
p='items/thm-qsmx-weighted-lieb-robinson.md'
t=changes[p]
start=t.index('2.1 At $u=0$'); end=t.index('\n3.1 ',start)
changes[p]=t[:start]+r'''2.1 At $u=0$, disjointness gives $C_B^\Lambda(S,0)=0$ when $S\cap Y=\varnothing$, while $C_B^\Lambda(S,u)\le2\|B\|$ for all supports and times by the commutator inequality and isometry of the dynamics. Iteration of step 1.1 produces time-ordered integrals over $0\le v_n\le\cdots\le v_1\le u$ and chains $Z_1,\ldots,Z_n$ with $Z_1\cap S\ne\varnothing$, $Z_{j+1}\cap Z_j\ne\varnothing$ and $Z_n\cap Y\ne\varnothing$, with product $\prod_{j=1}^n\|\Phi_{v_j}(Z_j)\|$. All support sums are finite. For the iteration remainder, put $Q_\Lambda=\sum_{\varnothing\ne Z\subseteq\Lambda}\sup_{v\in[0,T]}\|\Phi_v(Z)\|<\infty$, which is finite by norm continuity and compactness. Its absolute size after $n$ iterations is at most $2\|B\|(2Q_\Lambda u/\hbar)^n/n!$, so it tends to zero. This volume-dependent number is used only to discard the remainder. For the chain terms, define the time-dependent kernel $K_v(x,y)=\sum_{Z\subseteq\Lambda:\,x,y\in Z}\|\Phi_v(Z)\|$. At each fixed time tuple, summing over all endpoint and overlap sites overcounts each nonnegative interaction-chain term at least once. Thus the order-$n$ contribution for $S=X$ is at most $$2\|B\|(2/\hbar)^n\int_{0\le v_n\le\cdots\le v_1\le u}\sum_{x\in X,y\in Y}(K_{v_1}\cdots K_{v_n})(x,y)\,dv_n\cdots dv_1.$$ Kernel products here sum only over sites of the finite volume. No supremum over time has been moved inside an interaction sum for this bound. [given, F1, F3, step 1.1, algebra]
''' +t[end:]
t=changes[p];start=t.index('3.1 By [F1]');end=t.index('\n',start)
changes[p]=t[:start]+r'''3.1 By [F1], for each $v\in[0,T]$ separately, $K_v(x,y)\le M_GG(d_\infty(x,y))$. Induction using [F2] gives $$(K_{v_1}\cdots K_{v_n})(x,y)\le M_G^n C_G^{n-1}G(d_\infty(x,y))\qquad(n\ge1):$$ the intermediate-site convolution over the finite volume is bounded by the full nonnegative lattice convolution. This bound is uniform in every time tuple. Its integral over the time-ordered simplex is $u^n/n!$ times that bound. Substituting into step 2.1 and summing the convergent exponential series gives $C_B^\Lambda(X,u)\le \frac{2\|B\|}{C_G}(e^{2C_GM_Gu/\hbar}-1)\sum_{x\in X,y\in Y}G(d_\infty(x,y))$. The finite-volume remainder justifies the iteration limit; alternatively the displayed factorial majorant dominates every partial chain sum. Multiplication by $\|A\|$ proves the path estimate, including $A=0$. Applying the same time-ordered argument to the reversed interaction path, whose norm at every time is bounded by $M_G$, proves the inverse estimate. For a constant interaction take $u=|t|$; reversal changes its sign but not its norm. All constants in the resulting estimates depend only on $C_G,M_G$, not on the volume-dependent remainder bound. [given, F1, F2, step 2.1, algebra] ∎''' +t[end:]
alter('lem-qsmx-filtered-generator-locality',r'''\sum_{\substack{Z\subseteq\Lambda_n\\x,y\in Z}}\sup_s\|\Psi_{\Lambda_n}(Z,s)\|''',r'''\sum_{\substack{Z\subseteq\Lambda_n\\x,y\in Z}}\|\Psi_{\Lambda_n}(Z,s)\|''')
alter('lem-qsmx-filtered-generator-locality','Summing the shell estimate from step 2.1 over all $Y,k$ with $x,y\\in Y_k$ gives','For each fixed $s$, summing the shell estimate from step 2.1 over all $Y,k$ with $x,y\\in Y_k$ gives')
alter('lem-qsmx-filtered-generator-locality','This proves the uniform $F_\\rho$-norm bound.','The bound is independent of $s$ and $n$, so taking their suprema outside the support sum proves the stated uniform $F_\\rho$-norm bound. No sum of separate time suprema is asserted; all finite-volume sums are finite and their nonnegative shell bounds are dominated by the displayed convergent scalar series.')
for p,t in changes.items(): (root/p).write_text(t)
(base/'source-repairs.json').write_text(json.dumps({'reviewer':'/root/qsm_boundary','independent_review':False,'changes':[{'path':p,'before_raw_sha256':before[p]['raw_sha256'],'after_raw_sha256':hashlib.sha256(t.encode()).hexdigest()} for p,t in changes.items()]},indent=2)+'\n')
print('Repaired',len(changes),'sources; no manifest/page writes')
